const normalize = (value = '') => String(value)
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, ' ')
  .trim()
  .replace(/\s+/g, ' ');

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#039;');

const decodeHtml = (value = '') => String(value)
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/p>/gi, '\n')
  .replace(/<\/div>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;|&#160;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;|&apos;/gi, "'")
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/\r/g, '')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n\s*\n+/g, '\n')
  .trim();

const vendedores = {
  [normalize('Ana Souza')]: {
    nome: 'Ana Souza',
    email: 'ana.souza@empresa.example',
  },
  [normalize('Bruno Lima')]: {
    nome: 'Bruno Lima',
    email: 'bruno.lima@empresa.example',
  },
  [normalize('Carla Mendes')]: {
    nome: 'Carla Mendes',
    email: 'carla.mendes@empresa.example',
  },
};

const armazenamento = $getWorkflowStaticData('global');
armazenamento.rosProcessados ??= {};
const execucaoManual = typeof $execution !== 'undefined'
  && $execution.mode === 'manual';

const agora = Date.now();
const validadeHistorico = 365 * 24 * 60 * 60 * 1000;
for (const [chave, data] of Object.entries(armazenamento.rosProcessados)) {
  if (agora - Number(data) > validadeHistorico) {
    delete armazenamento.rosProcessados[chave];
  }
}

const resultado = [];

for (const item of $input.all()) {
  const email = item.json;
  const caixaOrigem = email.caixaOrigem;
  const assuntoOriginal = String(email.subject || '');

  const conteudoOriginal = email.body?.content
    || email.body
    || email.htmlBody
    || email.bodyPreview
    || '';
  const texto = decodeHtml(conteudoOriginal);

  const roMatch = texto.match(/N[uú]mero\s+da\s+Oportunidade\s*:\s*(\d+)/i)
    || assuntoOriginal.match(/\bRO\s*[:#-]?\s*(\d+)/i);
  const numeroRO = roMatch?.[1] || '';

  const nomeOportunidadeMatch = texto.match(
    /Nome\s+da\s+Oportunidade\s*:\s*([\s\S]*?)(?=\s*(?:Plano\s+do\s+programa\s+de\s+parceria|Nome\s+da\s+Conta\s+do\s+Parceiro|Termos\s+e\s+condi[cç][oõ]es|$))/i,
  );

  let nomeOportunidade = nomeOportunidadeMatch?.[1]?.trim() || '';
  if (!nomeOportunidade) {
    nomeOportunidade = assuntoOriginal
      .replace(/^.*?revis[aã]o\s*:\s*/i, '')
      .trim();
  }

  const refMatch = nomeOportunidade.match(/REF[:\-]?\s*([0-9]+)/i)
    || assuntoOriginal.match(/REF[:\-]?\s*([0-9]+)/i);
  const roReferencia = refMatch?.[1] || '';
  const isRenovacao = Boolean(roReferencia);

  const partes = nomeOportunidade.split('|').map((parte) => parte.trim());
  const cliente = partes[0] || '';
  const vendedorDell = partes[1] || '';
  const produto = partes.slice(2).join(' | ') || '';
  const vendedor = vendedores[normalize(vendedorDell)];

  const chaveUnica = numeroRO
    ? `ro:${numeroRO}`
    : `mensagem:${email.internetMessageId || email.id || assuntoOriginal}`;

  // Durante testes manuais, deixa o mesmo e-mail passar quantas vezes forem
  // necessárias. Com o workflow publicado, bloqueia o segundo envio do RO.
  if (!execucaoManual && armazenamento.rosProcessados[chaveUnica]) continue;
  if (!execucaoManual) armazenamento.rosProcessados[chaveUnica] = agora;

  const roExibicao = escapeHtml(numeroRO || 'Não identificado');
  const clienteExibicao = escapeHtml(cliente || 'Não identificado');
  const produtoExibicao = escapeHtml(produto || 'Não identificado');
  const vendedorExibicao = escapeHtml(vendedor?.nome || vendedorDell || 'Não identificado');
  const primeiroNome = escapeHtml((vendedor?.nome || vendedorDell || 'Vendedor').split(' ')[0]);

  const htmlEmail = `
<!doctype html>
<html lang="pt-BR">
  <body style="margin:0;padding:0;background:#f3f5f7;font-family:Arial,Helvetica,sans-serif;color:#1f2933;">
    <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background:#f3f5f7;padding:20px 12px;">
      <tr>
        <td align="center">
          <table role="presentation" width="620" cellspacing="0" cellpadding="0" border="0" style="width:100%;max-width:620px;background:#ffffff;border:1px solid #e2e6ea;border-radius:8px;overflow:hidden;">
            <tr>
              <td align="center" style="padding:12px 24px;background:#0a2222;border-bottom:4px solid #42e47d;">
                <img src="https://example.com/imagens/logo-empresa.png" alt="Empresa Exemplo" width="135" style="display:block;width:135px;max-width:100%;height:auto;border:0;">
              </td>
            </tr>
            <tr>
              <td style="padding:22px 26px 18px;">
                <p style="margin:0 0 13px;font-size:14px;line-height:1.5;color:#374151;">Olá, ${primeiroNome}.</p>
                <h1 style="margin:0 0 7px;font-size:20px;line-height:1.3;color:#0a2222;">Registro de Oportunidade submetido</h1>
                <p style="margin:0 0 17px;font-size:13px;line-height:1.5;color:#52606d;">O registro foi enviado à Dell e está aguardando análise.</p>

                <table role="presentation" cellspacing="0" cellpadding="0" border="0" style="margin:0 0 18px;">
                  <tr>
                    <td style="padding:6px 11px;background:#eaf9f0;border:1px solid #bce8cc;border-radius:20px;font-size:12px;font-weight:bold;color:#167744;">
                      Submetido • Pendente de aprovação
                    </td>
                  </tr>
                </table>

                <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="border:1px solid #e2e8ed;border-radius:6px;border-collapse:separate;overflow:hidden;font-size:13px;line-height:1.45;">
                  <tr>
                    <td width="92" style="padding:9px 12px;background:#f6f8f8;border-bottom:1px solid #e2e8ed;color:#5f6b76;font-weight:bold;">RO</td>
                    <td style="padding:9px 12px;border-bottom:1px solid #e2e8ed;color:#0a2222;font-weight:bold;">${roExibicao}</td>
                  </tr>
                  <tr>
                    <td width="92" style="padding:9px 12px;background:#f6f8f8;border-bottom:1px solid #e2e8ed;color:#5f6b76;font-weight:bold;">Cliente</td>
                    <td style="padding:9px 12px;border-bottom:1px solid #e2e8ed;">${clienteExibicao}</td>
                  </tr>
                  <tr>
                    <td width="92" style="padding:9px 12px;background:#f6f8f8;color:#5f6b76;font-weight:bold;">Produto</td>
                    <td style="padding:9px 12px;">${produtoExibicao}</td>
                  </tr>
                </table>

                <p style="margin:17px 0 0;padding-top:13px;border-top:1px solid #edf0f2;font-size:11px;line-height:1.45;color:#7b8794;">Mensagem automática do fluxo de Registro de Oportunidades da Empresa Exemplo.</p>
              </td>
            </tr>
          </table>
        </td>
      </tr>
    </table>
  </body>
</html>`;

  const htmlAlerta = `
<!doctype html>
<html lang="pt-BR">
  <body style="font-family:Arial,Helvetica,sans-serif;color:#252525;">
    <img src="https://example.com/imagens/logo-empresa.png" alt="Empresa Exemplo" width="180" style="display:block;width:180px;height:auto;margin-bottom:22px;">
    <h2 style="color:#b42318;">Vendedor não identificado</h2>
    <p>O fluxo recebeu um e-mail da Dell, mas não encontrou uma correspondência segura na lista de vendedores. Nenhum e-mail foi enviado ao vendedor.</p>
    <p><strong>RO:</strong> ${roExibicao}<br>
    <strong>Nome identificado:</strong> ${vendedorExibicao}<br>
    <strong>Cliente:</strong> ${clienteExibicao}<br>
    <strong>Produto:</strong> ${produtoExibicao}<br>
    <strong>Caixa de origem:</strong> ${escapeHtml(caixaOrigem)}</p>
  </body>
</html>`;

  resultado.push({
    json: {
      caixaOrigem,
      numeroRO,
      roReferencia,
      isRenovacao,
      cliente,
      produto,
      vendedorDell,
      vendedorEncontrado: Boolean(vendedor),
      nomeVendedor: vendedor?.nome || vendedorDell || '',
      emailVendedor: vendedor?.email || '',
      assuntoEmail: `RO ${numeroRO || 'não identificado'} submetido — ${cliente || 'cliente não identificado'}`,
      htmlEmail,
      assuntoAlerta: `ATENÇÃO — vendedor não identificado no RO ${numeroRO || 'sem número'}`,
      htmlAlerta,
      mensagemDellId: email.id || '',
      internetMessageId: email.internetMessageId || '',
      recebidoEm: email.receivedDateTime || '',
    },
  });
}

return resultado;
